function validate([words, separator]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 20) return 'Each word has 1 to 20 characters.';
    if (!/^[a-z.,|$#@]+$/.test(word)) return 'Words use only lowercase letters and . , | $ # @';
  }
  if (typeof separator !== 'string' || separator.length !== 1 || !'.,|$#@'.includes(separator)) return 'separator is one of . , | $ # @';
  return null;
}

