function splitWordsBySeparator(words, separator) {
  const result = [];
  for (const word of words) {
    let piece = '';
    for (const ch of word) {
      if (ch === separator) {
        if (piece.length > 0) {
          result.push(piece);
        }
        piece = '';
      } else {
        piece += ch;
      }
    }
    if (piece.length > 0) {
      result.push(piece);
    }
  }
  return result;
}

