function generate(rand, size) {
  const symbols = '.,|$#@';
  const separator = symbols[Math.floor(rand() * symbols.length)];
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'ab';
  const count = size === 'large' ? 100 : 1 + Math.floor(rand() * 6);
  const sepRate = rand() * 0.6;
  const words = [];
  for (let i = 0; i < count; i++) {
    const length = size === 'large' ? 20 : 1 + Math.floor(rand() * 8);
    let word = '';
    for (let j = 0; j < length; j++) {
      const roll = rand();
      if (roll < sepRate) word += separator;
      else if (roll < sepRate + 0.1) word += symbols[Math.floor(rand() * symbols.length)];
      else word += letters[Math.floor(rand() * letters.length)];
    }
    words.push(word);
  }
  return [words, separator];
}
